Built as a single self-contained `AccountSettingsScreen.tsx` — no external UI/icon libraries required, works with React Navigation or any stack. Key platform decisions: 48dp/44pt-safe row heights, iOS destructive action via `ActionSheetIOS` vs Android via a two-button `Alert` dialog, light/dark tokens following the "nearer surfaces get lighter" ladder, and rows sized with `minHeight` (not fixed `height`) so Dynamic Type/large fonts can grow the row instead of truncating.

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useState } from 'react';
import {
  ActionSheetIOS,
  ActivityIndicator,
  Alert,
  Image,
  Platform,
  Pressable,
  ScrollView,
  StatusBar,
  StyleSheet,
  Switch,
  Text,
  View,
  useColorScheme,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context'; // peer dep: react-native-safe-area-context

// ---------- Tokens (semantic, theme-aware; dark = lighter-is-nearer ladder) ----------

const LIGHT_TOKENS = {
  bgApp: '#F2F2F7',
  bgSurface: '#FFFFFF',
  bgSurfaceRaised: '#FFFFFF',
  borderSubtle: '#E3E3E8',
  textPrimary: '#1C1C1E',
  textMuted: '#6B6B70',
  dangerText: '#D70015',
  accentSolid: '#007AFF',
  onAccent: '#FFFFFF',
};

const DARK_TOKENS = {
  bgApp: '#0B0B0D', // avoid pure black for large areas
  bgSurface: '#1C1C1E',
  bgSurfaceRaised: '#242426',
  borderSubtle: '#3A3A3C',
  textPrimary: '#F2F2F2',
  textMuted: '#9B9BA1',
  dangerText: '#FF453A',
  accentSolid: '#0A84FF',
  onAccent: '#FFFFFF',
};

type Tokens = typeof LIGHT_TOKENS;

const ROW_MIN_HEIGHT = 48; // satisfies both iOS (44pt) and Android (48dp) target floors

// ---------- Types ----------

export type AccountUser = {
  name: string;
  email: string;
  avatarUrl?: string;
};

export type SettingsRoute = 'notifications' | 'privacy' | 'appearance' | 'help' | 'about';

export type AccountSettingsScreenProps = {
  user: AccountUser;
  isBiometricEnabled: boolean;
  onToggleBiometric: (enabled: boolean) => void;
  onEditProfile: () => void;
  onNavigateTo: (route: SettingsRoute) => void;
  onLogOut: () => void;
  /** Should perform the real deletion and throw on failure. */
  onDeleteAccount: () => Promise<void>;
};

// ---------- Small building blocks ----------

function Avatar({ user, tokens }: { user: AccountUser; tokens: Tokens }) {
  if (user.avatarUrl) {
    return <Image source={{ uri: user.avatarUrl }} style={styles.avatarImage} accessibilityIgnoresInvertColors />;
  }
  const initials = user.name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('');
  return (
    <View style={[styles.avatarFallback, { backgroundColor: tokens.accentSolid }]}>
      <Text style={[styles.avatarInitials, { color: tokens.onAccent }]} allowFontScaling={false}>
        {initials}
      </Text>
    </View>
  );
}

function ProfileRow({
  user,
  tokens,
  onPress,
}: {
  user: AccountUser;
  tokens: Tokens;
  onPress: () => void;
}) {
  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`Edit profile for ${user.name}`}
      hitSlop={8}
      style={({ pressed }) => [
        styles.profileRow,
        { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle, opacity: pressed ? 0.7 : 1 },
      ]}
    >
      <Avatar user={user} tokens={tokens} />
      <View style={styles.profileText}>
        <Text style={[styles.profileName, { color: tokens.textPrimary }]}>{user.name}</Text>
        <Text style={[styles.profileEmail, { color: tokens.textMuted }]}>{user.email}</Text>
      </View>
      <Text style={[styles.chevron, { color: tokens.textMuted }]} allowFontScaling={false}>
        ›
      </Text>
    </Pressable>
  );
}

function SettingsRow({
  label,
  tokens,
  onPress,
  rightElement,
  showChevron = true,
  destructive = false,
  disabled = false,
  isLast = false,
  accessibilityHint,
}: {
  label: string;
  tokens: Tokens;
  onPress?: () => void;
  rightElement?: React.ReactNode;
  showChevron?: boolean;
  destructive?: boolean;
  disabled?: boolean;
  isLast?: boolean;
  accessibilityHint?: string;
}) {
  return (
    <Pressable
      onPress={onPress}
      disabled={disabled}
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityHint={accessibilityHint}
      accessibilityState={{ disabled, busy: disabled }}
      style={({ pressed }) => [
        styles.row,
        !isLast && { borderBottomWidth: 1, borderBottomColor: tokens.borderSubtle },
        { opacity: pressed ? 0.6 : disabled ? 0.5 : 1 },
      ]}
    >
      <Text
        style={[styles.rowLabel, { color: destructive ? tokens.dangerText : tokens.textPrimary }]}
      >
        {label}
      </Text>
      <View style={styles.rowRight}>
        {rightElement}
        {showChevron && !rightElement && (
          <Text style={[styles.chevron, { color: tokens.textMuted }]} allowFontScaling={false}>
            ›
          </Text>
        )}
      </View>
    </Pressable>
  );
}

function Section({
  title,
  tokens,
  children,
}: {
  title?: string;
  tokens: Tokens;
  children: React.ReactNode;
}) {
  return (
    <View style={styles.section}>
      {title ? (
        <Text style={[styles.sectionTitle, { color: tokens.textMuted }]}>{title}</Text>
      ) : null}
      <View
        style={[styles.sectionBody, { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle }]}
      >
        {children}
      </View>
    </View>
  );
}

// ---------- Screen ----------

export default function AccountSettingsScreen({
  user,
  isBiometricEnabled,
  onToggleBiometric,
  onEditProfile,
  onNavigateTo,
  onLogOut,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const scheme = useColorScheme();
  const isDark = scheme === 'dark';
  const tokens = isDark ? DARK_TOKENS : LIGHT_TOKENS;
  const [isDeleting, setIsDeleting] = useState(false);

  const runDelete = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
    } catch {
      Alert.alert('Something went wrong', "We couldn't delete your account. Please try again.");
    } finally {
      setIsDeleting(false);
    }
  }, [onDeleteAccount]);

  const confirmDelete = useCallback(() => {
    const title = 'Delete account?';
    const message =
      'This permanently deletes your account and all of your data. This cannot be undone.';

    if (Platform.OS === 'ios') {
      ActionSheetIOS.showActionSheetWithOptions(
        {
          title,
          message,
          options: ['Delete Account', 'Cancel'],
          destructiveButtonIndex: 0,
          cancelButtonIndex: 1,
        },
        (index) => {
          if (index === 0) runDelete();
        },
      );
    } else {
      Alert.alert(title, message, [
        { text: 'Cancel', style: 'cancel' },
        { text: 'Delete', style: 'destructive', onPress: runDelete },
      ]);
    }
  }, [runDelete]);

  return (
    <SafeAreaView style={[styles.screen, { backgroundColor: tokens.bgApp }]} edges={['top', 'bottom']}>
      <StatusBar barStyle={isDark ? 'light-content' : 'dark-content'} backgroundColor={tokens.bgApp} />
      <ScrollView contentContainerStyle={styles.content} contentInsetAdjustmentBehavior="automatic">
        <ProfileRow user={user} tokens={tokens} onPress={onEditProfile} />

        <Section tokens={tokens}>
          <SettingsRow label="Notifications" tokens={tokens} onPress={() => onNavigateTo('notifications')} />
          <SettingsRow label="Privacy & Security" tokens={tokens} onPress={() => onNavigateTo('privacy')} />
          <SettingsRow label="Appearance" tokens={tokens} onPress={() => onNavigateTo('appearance')} />
          <SettingsRow
            label="Face ID / Biometric login"
            tokens={tokens}
            showChevron={false}
            rightElement={
              <Switch
                value={isBiometricEnabled}
                onValueChange={onToggleBiometric}
                trackColor={{ false: tokens.borderSubtle, true: tokens.accentSolid }}
              />
            }
          />
          <SettingsRow label="Help & Support" tokens={tokens} onPress={() => onNavigateTo('help')} />
          <SettingsRow label="About" tokens={tokens} onPress={() => onNavigateTo('about')} isLast />
        </Section>

        <Section tokens={tokens}>
          <SettingsRow label="Log Out" tokens={tokens} onPress={onLogOut} isLast />
        </Section>

        <Section title="Danger Zone" tokens={tokens}>
          <SettingsRow
            label="Delete Account"
            tokens={tokens}
            destructive
            showChevron={false}
            disabled={isDeleting}
            onPress={confirmDelete}
            accessibilityHint="Permanently deletes your account and all of your data"
            rightElement={isDeleting ? <ActivityIndicator color={tokens.dangerText} /> : null}
            isLast
          />
        </Section>
        <Text style={[styles.footnote, { color: tokens.textMuted }]}>
          Deleting your account is permanent and cannot be undone.
        </Text>
      </ScrollView>
    </SafeAreaView>
  );
}

// ---------- Styles ----------

const styles = StyleSheet.create({
  screen: { flex: 1 },
  content: { padding: 16, paddingBottom: 32 },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 64,
    padding: 16,
    borderRadius: 12,
    borderWidth: 1,
    marginBottom: 24,
  },
  avatarImage: { width: 56, height: 56, borderRadius: 28 },
  avatarFallback: { width: 56, height: 56, borderRadius: 28, alignItems: 'center', justifyContent: 'center' },
  avatarInitials: { fontSize: 20, fontWeight: '600' },
  profileText: { flex: 1, marginLeft: 12, marginRight: 8 },
  profileName: { fontSize: 17, fontWeight: '600' },
  profileEmail: { fontSize: 14, marginTop: 2 },
  section: { marginBottom: 24 },
  sectionTitle: { fontSize: 13, fontWeight: '600', marginBottom: 8, marginLeft: 4 },
  sectionBody: { borderRadius: 12, borderWidth: 1, overflow: 'hidden' },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: ROW_MIN_HEIGHT,
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  rowLabel: { flex: 1, fontSize: 16 },
  rowRight: { flexDirection: 'row', alignItems: 'center', marginLeft: 12 },
  chevron: { fontSize: 20 },
  footnote: { fontSize: 13, marginTop: 4, marginHorizontal: 4 },
});
```

Usage assumes the host screen (or a thin wrapper/navigator) supplies `user`, the toggle/nav/log-out/delete handlers, and that `onDeleteAccount` performs the real API call and resolves/rejects accordingly. Only external dependency is `react-native-safe-area-context`; drop the `SafeAreaView` import and swap for a plain `View` if you'd rather not add it.
